<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/admin_layout.php'))require_once __DIR__.'/../app/admin_layout.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';sk1380_admin_header('Service Marketplace Pro');$s=['providers'=>0,'pending_providers'=>0,'active_providers'=>0,'open_requests'=>0,'active_orders'=>0,'completed'=>0,'package_requests'=>0];$providers=[];$orders=[];$err='';try{$s=sk1380_stats();$q=sk1380_db()->prepare('SELECT p.* FROM service_provider_profiles_v1380 p WHERE p.tenant_id=? ORDER BY FIELD(p.status,"pending","approved","suspended","rejected"),p.id DESC LIMIT 12');$q->execute([sk1380_tid()]);$providers=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$q=sk1380_db()->prepare('SELECT o.*,p.business_name,p.display_name FROM service_orders_v1380 o JOIN service_provider_profiles_v1380 p ON p.id=o.provider_id WHERE o.tenant_id=? ORDER BY o.id DESC LIMIT 12');$q->execute([sk1380_tid()]);$orders=$q->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){$err=$e->getMessage();}?><div class="svc-admin"><?php if($err):?><div class="notice err"><b>Service runtime check failed.</b> <?=sk1380_h($err)?></div><?php endif;?><section class="admin-hero"><div><span>SERVICE PROVIDER PRO</span><h1>Local Service Marketplace Control Center</h1><p>Provider approvals, jobs, customer requests, packages, Fast Service and paid visibility from one dashboard.</p></div><nav><a href="/admin/service-providers.php">Providers</a><a href="/admin/service-orders.php">Orders</a><a href="/admin/service-packages.php">Packages</a><a href="/admin/service-promotions.php">Promotions</a><a href="/admin/service-settings.php">Settings</a></nav></section><div class="metric-grid seven"><article><span>Providers</span><b><?=$s['providers']?></b></article><article><span>Pending approval</span><b><?=$s['pending_providers']?></b></article><article><span>Approved</span><b><?=$s['active_providers']?></b></article><article><span>Open requests</span><b><?=$s['open_requests']?></b></article><article><span>Active jobs</span><b><?=$s['active_orders']?></b></article><article><span>Completed</span><b><?=$s['completed']?></b></article><article><span>Package approvals</span><b><?=$s['package_requests']?></b></article></div><div class="admin-cols"><section><header><h2>Provider Approval Queue</h2><a href="/admin/service-providers.php">Manage all</a></header><?php foreach($providers as $p):?><div class="admin-row"><div><b><?=sk1380_h($p['business_name']?:$p['display_name'])?></b><small><?=sk1380_h($p['area'])?> · <?=sk1380_h($p['verification_status'])?></small></div><strong class="state <?=sk1380_h($p['status'])?>"><?=sk1380_h($p['status'])?></strong></div><?php endforeach;?></section><section><header><h2>Recent Orders</h2><a href="/admin/service-orders.php">Manage all</a></header><?php foreach($orders as $o):?><a class="admin-row" href="/service-order.php?id=<?=$o['id']?>"><div><b><?=sk1380_h($o['order_code'].' · '.$o['service_title'])?></b><small><?=sk1380_h($o['business_name']?:$o['display_name'])?></small></div><strong><?=sk1380_h($o['status'])?></strong></a><?php endforeach;?></section></div></div><?php sk1380_admin_footer();